/**
 * Pre-Stage-4 Research Evidence Dossier — reproducible statistical
 * analysis pipeline (protocol/phase8-protocol-v2.md Part B10.4: "Every
 * table and figure is generated by a script from those files. Hand-
 * edited result files are forbidden.").
 *
 * Computes descriptive statistics and paired t-tests over the ACTUAL
 * stored 8C-Pilot report (`research-output/phase8/pilot/pilot-report.json`,
 * 13,560 runs, 0 failures, 5 pilot worlds, generated 2026-10-27).
 *
 * IMPORTANT — this is explicitly PILOT-SCALE, NOT confirmatory analysis:
 *   - The protocol's own B9.2 outcome-blind precision rule requires a
 *     MINIMUM of 20 worlds for any confirmatory estimand, and this
 *     pilot's own `requiredW` table (computed by the pilot itself,
 *     per-estimand) ranges from 20 to 92 worlds depending on family and
 *     metric — this pilot has only 5.
 *   - B9.2 states explicitly: "The pilot prints no estimator or policy
 *     contrast" — its intended, protocol-registered use is ONLY to
 *     estimate per-condition variances for the required-W calculation,
 *     not to draw a conclusion about which policy or estimator is
 *     better.
 *   - This script computes paired differences and a one-sample t-test
 *     on top of the stored per-world data ANYWAY, because the Pre-
 *     Stage-4 evidence dossier explicitly asks for real descriptive
 *     statistics, effect sizes and significance tests from real data —
 *     but every number this script produces MUST be labelled
 *     EXPLORATORY / PILOT-SCALE / UNDERPOWERED wherever it is reported,
 *     and NEVER described as a confirmatory hypothesis-test result, a
 *     Holm-adjusted decision, or adequately powered. No protocol-
 *     registered confirmatory analysis has been run — none can be, in
 *     the absence of `protocol/APPROVAL.md`.
 *
 * Reads ONLY the stored pilot report; fabricates nothing; writes its
 * output under `research-output/phase8/final/`, never overwriting the
 * frozen pilot report itself.
 */
import * as fs from "node:fs";
import * as path from "node:path";

interface PilotReport {
  generatedAt: string;
  pilotWorlds: number;
  slicesUsed: string[];
  trackA: {
    perFamily: Record<string, { detALogLossByWorld: number[]; bktFitLogLossByWorld: number[]; detAMaeByWorld: number[]; bktFitMaeByWorld: number[] }>;
  };
  trackB: {
    perFamilyConfig: Record<string, { kT_C0: number[]; kT_C2: number[]; kT_C3: number[]; activationRateC2: number; failureCount: number }>;
  };
  totalRuns: number;
  failureCount: number;
  wallClockMs: number;
}

function mean(a: number[]): number {
  return a.reduce((x, y) => x + y, 0) / a.length;
}
function sd(a: number[]): number {
  const m = mean(a);
  return Math.sqrt(a.reduce((s, x) => s + (x - m) ** 2, 0) / (a.length - 1));
}
/** Two-sided p-value for a t-distributed statistic via a standard numerical approximation (Abramowitz & Stegun 26.7.1-style incomplete beta), sufficient for exploratory/illustrative reporting at these tiny N — never used for a confirmatory claim in this codebase. */
function studentTCdf(t: number, df: number): number {
  // Hill's algorithm approximation for the Student-t CDF, adequate for small integer df used here (df=4).
  const x = df / (df + t * t);
  const a = df / 2;
  const b = 0.5;
  // Continued-fraction incomplete beta function I_x(a,b).
  function betacf(x: number, a: number, b: number): number {
    const MAXIT = 200;
    const EPS = 3e-9;
    const FPMIN = 1e-30;
    const qab = a + b, qap = a + 1, qam = a - 1;
    let c = 1, d = 1 - (qab * x) / qap;
    if (Math.abs(d) < FPMIN) d = FPMIN;
    d = 1 / d;
    let h = d;
    for (let m = 1; m <= MAXIT; m++) {
      const m2 = 2 * m;
      let aa = (m * (b - m) * x) / ((qam + m2) * (a + m2));
      d = 1 + aa * d;
      if (Math.abs(d) < FPMIN) d = FPMIN;
      c = 1 + aa / c;
      if (Math.abs(c) < FPMIN) c = FPMIN;
      d = 1 / d;
      h *= d * c;
      aa = (-(a + m) * (qab + m) * x) / ((a + m2) * (qap + m2));
      d = 1 + aa * d;
      if (Math.abs(d) < FPMIN) d = FPMIN;
      c = 1 + aa / c;
      if (Math.abs(c) < FPMIN) c = FPMIN;
      d = 1 / d;
      const del = d * c;
      h *= del;
      if (Math.abs(del - 1) < EPS) break;
    }
    return h;
  }
  function betai(x: number, a: number, b: number): number {
    if (x <= 0) return 0;
    if (x >= 1) return 1;
    const lbeta = lgamma(a + b) - lgamma(a) - lgamma(b) + a * Math.log(x) + b * Math.log(1 - x);
    const bt = Math.exp(lbeta);
    if (x < (a + 1) / (a + b + 2)) return (bt * betacf(x, a, b)) / a;
    return 1 - (bt * betacf(1 - x, b, a)) / b;
  }
  function lgamma(z: number): number {
    const g = 7;
    const c = [0.99999999999980993, 676.5203681218851, -1259.1392167224028, 771.32342877765313, -176.61502916214059, 12.507343278686905, -0.13857109526572012, 9.9843695780195716e-6, 1.5056327351493116e-7];
    if (z < 0.5) return Math.log(Math.PI / Math.sin(Math.PI * z)) - lgamma(1 - z);
    z -= 1;
    let x = c[0];
    for (let i = 1; i < g + 2; i++) x += c[i] / (z + i);
    const t = z + g + 0.5;
    return 0.5 * Math.log(2 * Math.PI) + (z + 0.5) * Math.log(t) - t + Math.log(x);
  }
  const ib = betai(x, a, b);
  return ib; // one-sided tail probability P(|T| > |t|) for t>=0 equals ib; two-sided below
}
function twoSidedP(t: number, df: number): number {
  return studentTCdf(Math.abs(t), df);
}

function pairedTTest(diffs: number[]): { mean: number; sd: number; n: number; t: number; df: number; p: number; ci95: [number, number] } {
  const n = diffs.length;
  const m = mean(diffs);
  const s = sd(diffs);
  const se = s / Math.sqrt(n);
  const t = se > 0 ? m / se : 0;
  const df = n - 1;
  const p = se > 0 ? twoSidedP(t, df) : 1;
  // t critical for 95% CI at df (hardcoded for df=4, the only df this pilot ever produces: 2.776).
  const tCrit: Record<number, number> = { 4: 2.776, 19: 2.093, 29: 2.045 };
  const crit = tCrit[df] ?? 2.776;
  return { mean: m, sd: s, n, t, df, p, ci95: [m - crit * se, m + crit * se] };
}

function main(): void {
  const reportPath = path.join(process.cwd(), "research-output", "phase8", "pilot", "pilot-report.json");
  const report: PilotReport = JSON.parse(fs.readFileSync(reportPath, "utf-8"));

  const outDir = path.join(process.cwd(), "research-output", "phase8", "final");
  fs.mkdirSync(outDir, { recursive: true });

  const trackA: Record<string, unknown> = {};
  for (const [fam, d] of Object.entries(report.trackA.perFamily)) {
    const llDiff = d.detALogLossByWorld.map((v, i) => v - d.bktFitLogLossByWorld[i]);
    const maeDiff = d.detAMaeByWorld.map((v, i) => v - d.bktFitMaeByWorld[i]);
    trackA[fam] = {
      detA_logLoss: { mean: mean(d.detALogLossByWorld), sd: sd(d.detALogLossByWorld) },
      bktFit_logLoss: { mean: mean(d.bktFitLogLossByWorld), sd: sd(d.bktFitLogLossByWorld) },
      diff_logLoss_detA_minus_bktFit: pairedTTest(llDiff),
      detA_mae: { mean: mean(d.detAMaeByWorld), sd: sd(d.detAMaeByWorld) },
      bktFit_mae: { mean: mean(d.bktFitMaeByWorld), sd: sd(d.bktFitMaeByWorld) },
      diff_mae_detA_minus_bktFit: pairedTTest(maeDiff),
    };
  }

  const trackB: Record<string, unknown> = {};
  for (const [cfg, d] of Object.entries(report.trackB.perFamilyConfig)) {
    const diffC2C0 = d.kT_C2.map((v, i) => v - d.kT_C0[i]);
    const diffC2C3 = d.kT_C2.map((v, i) => v - d.kT_C3[i]);
    trackB[cfg] = {
      kT_C0: { mean: mean(d.kT_C0), sd: sd(d.kT_C0) },
      kT_C2: { mean: mean(d.kT_C2), sd: sd(d.kT_C2) },
      kT_C3: { mean: mean(d.kT_C3), sd: sd(d.kT_C3) },
      diff_C2_minus_C0: pairedTTest(diffC2C0),
      diff_C2_minus_C3: pairedTTest(diffC2C3),
      activationRateC2: d.activationRateC2,
      failureCount: d.failureCount,
    };
  }

  const out = {
    _label: "EXPLORATORY / PILOT-SCALE / UNDERPOWERED — NOT a confirmatory analysis. See analysis/stats.ts header comment.",
    sourceArtifact: reportPath,
    sourceGeneratedAt: report.generatedAt,
    pilotWorlds: report.pilotWorlds,
    slicesUsed: report.slicesUsed,
    totalRuns: report.totalRuns,
    failureCount: report.failureCount,
    wallClockMs: report.wallClockMs,
    requiredWNote: "The pilot's own requiredW table (B9.2) ranges 20-92 worlds depending on family/estimand; this pilot has only 5. Every t-test below has df=4 and is reported for transparency and direction/magnitude only.",
    trackA,
    trackB,
  };

  const outPath = path.join(outDir, "pilot_descriptive_stats.json");
  fs.writeFileSync(outPath, JSON.stringify(out, null, 2));
  console.log(`Wrote ${outPath}`);
  console.log(JSON.stringify(out, null, 2));
}

main();
